messages.content:
Update playwright.config.ts: add a Firefox project using Desktop Firefox next to Chromium and set screenshot to only-on-failure in shared use. Keep trace and baseURL unchanged.

import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
	expect: {
		timeout: 5000
	},
	forbidOnly: !!process.env.CI,
	fullyParallel: true,
	projects: [
		{
			name: 'chromium',
			use: { ...devices['Desktop Chrome'] }
		}
	],
	reporter: 'line',
	retries: process.env.CI ? 2 : 0,
	testDir: 'tests/e2e',
	testMatch: ['**/*.e2e.ts'],
	timeout: 30000,
	use: {
		baseURL: 'http://localhost:8181',
		trace: 'on-first-retry'
	},
	webServer: {
		command: 'npm run build && npx http-server ./dist -p 8181',
		port: 8181,
		reuseExistingServer: !process.env.CI,
		timeout: 120000
	},
	workers: process.env.CI ? 1 : undefined
});

